content.content:
1	/* ============================================
2	   共通リセット
3	   ============================================ */
4	html { scroll-behavior: smooth; }
5	@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } * { animation: none !important; } }
6	* { box-sizing: border-box; }
7	body { margin: 0; font-family: "Zen Kaku Gothic New", "Archivo", system-ui, sans-serif; -webkit-font-smoothing: antialiased; }
8	a { color: inherit; text-decoration: none; }
9	
10	/* ページテーマ（body class="page-xxx"） */
11	/* page-portfolio（404）・page-privacy はTOPページと同じ新配色。page-pianist・page-horror は現行デザインを維持（別途リニューアル予定のため変更しない） */
12	body.page-portfolio { background: #EAF6FB; color: #10485F; }
13	body.page-privacy { background: #EAF6FB; color: #10485F; }
14	body.page-pianist { background: #08080A; color: #F2EFE9; }
15	body:has(.pn-shell) {
16	  color: #F2EFE9;
17	  background: linear-gradient(180deg,rgba(8,8,10,0.4),rgba(8,8,10,0.65)), url("images/25253200_l.webp") center / cover no-repeat fixed, #08080A;
18	}
19	body:has(.top-shell) {
20	  background: url("images/26388934.webp") center / cover no-repeat fixed;
21	}
22	body.page-portfolio a:hover { color: #B57E00; }
23	body.page-privacy a:hover { color: #B57E00; }
24	body.page-pianist a:hover { color: #E4C97E; }
25	.pn-shell a:hover { color: #E4C97E; }
26	body.page-portfolio ::selection,
27	body.page-privacy ::selection { background: #FFE79A; color: #10485F; }
28	
29	body.page-horror { background: #07070A; color: #D6D2CB; }
30	body.page-horror a:hover { color: #9B2C22; }
31	
32	/* ============================================
33	   キーフレームアニメーション
34	   ============================================ */
35	@keyframes scrollcue { 0% { transform: translateY(-100%); } 100% { transform: translateY(100%); } }
36	@keyframes fadeup { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: none; } }
37	@keyframes flick { 0%,100% { opacity: .85; } 47% { opacity: .85; } 48% { opacity: .35; } 52% { opacity: .9; } 70% { opacity: .6; } }
38	@keyframes slowfade { from { opacity: 0; } to { opacity: 1; } }
39	@keyframes floatY { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-9px); } }
40	@keyframes floatY2 { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-14px); } }
41	@keyframes sway { 0%,100% { transform: translateX(0); } 50% { transform: translateX(-40px); } }
42	@keyframes nodeGlow { 0%,100% { box-shadow: 0 0 0 0 rgba(255,199,44,0); } 50% { box-shadow: 0 0 0 7px rgba(255,199,44,0.16); } }
43	@keyframes pulseRing { 0% { transform: scale(1); opacity: .55; } 70% { transform: scale(2.1); opacity: 0; } 100% { transform: scale(2.1); opacity: 0; } }
44	
45	/* ============================================
46	   共通ユーティリティ（複数ブロックで使い回すパーツ）
47	   ============================================ */
48	.container { max-width: 1280px; margin: 0 auto; }
49	.sub-container { max-width: 1180px; margin: 0 auto; }
50	.text-block { margin: 0; }
51	
52	.eyebrow { font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.26em; color: #B57E00; margin: 0 0 28px; }
53	.eyebrow--tight { margin-bottom: 24px; }
54	
55	.section { position: relative; padding: clamp(56px,8cqw,130px) clamp(20px,6cqw,80px) clamp(64px,9cqw,130px); }
56	.section--first { min-height: 100svh; padding: clamp(104px,13cqw,150px) clamp(20px,6cqw,80px) clamp(64px,8cqw,90px); overflow: hidden; }
57	.section--about { padding-top: clamp(72px,10cqw,150px); padding-bottom: clamp(56px,8cqw,120px); }
58	.section--works { padding-top: clamp(48px,7cqw,120px); }
59	.section--next { overflow: hidden; }
60	.section--contact { padding: clamp(64px,10cqw,160px) clamp(20px,6cqw,80px) clamp(72px,10cqw,160px); }
61	.section__head { display: flex; flex-direction: column; align-items: center; text-align: center; gap: 14px; margin-bottom: clamp(36px,6cqw,80px); }
62	.section__eyebrow { font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.26em; color: #B57E00; margin: 0; }
63	.section__heading { margin: 0; font-weight: 500; font-size: clamp(23px,3.6cqw,46px); line-height: 1.55; letter-spacing: -0.01em; color: #0E4257; }
64	.section__intro { text-align: center; }
65	
66	.wave-divider { line-height: 0; position: relative; }
67	.wave-divider--to-dark { background: linear-gradient(180deg,#2A97C4,#0E4257); }
68	.wave-divider__svg { display: block; width: 100%; height: clamp(44px,7cqw,84px); }
69	.wave-divider__badge { position: absolute; left: 50%; top: 50%; margin-left: -17px; margin-top: -17px; width: 34px; height: 34px; }
70	.wave-divider__badge .float-badge__icon { width: 18px; height: 18px; }
71	
72	/* ============================================
73	   shell（各ページ共通の外枠カード）
74	   ============================================ */
75	.shell {
76	  container-type: inline-size;
77	  max-width: 375px;
78	  margin: 0 auto;
79	  min-height: 100svh;
80	  position: relative;
81	  overflow-x: hidden;
82	  display: flex;
83	  flex-direction: column;
84	  background: #F5F8FC;
85	  box-shadow: 0 0 80px rgba(18,36,63,0.16);
86	}
87	.shell--muted { background: #F0F5FA; }
88	.shell--dark { background: #0B0B0C; box-shadow: 0 0 80px rgba(0,0,0,0.5); }
89	
90	.skip-link { position: absolute; left: -9999px; top: 0; background: #12243F; color: #F5F8FC; padding: 12px 18px; z-index: 200; }
91	.skip-link:focus { left: 12px; top: 12px; }
92	
93	/* ============================================
94	   top-shell（TOPページ専用の外枠カード。.shellは他ページ共有のため触らずこちらを使う）
95	   ============================================ */
96	.top-shell {
97	  container-type: inline-size;
98	  max-width: 375px;
99	  margin: 0 auto;
100	  min-height: 100svh;
101	  position: relative;
102	  overflow-x: clip;
103	  display: flex;
104	  flex-direction: column;
105	  background: linear-gradient(180deg,#F4FBFE 0%,#EAF7FC 14%,#DCF1F9 34%,#E9F7FC 52%,#DDF2F9 72%,#F1FAFD 100%);
106	  box-shadow: 0 0 90px rgba(16,72,95,0.16);
107	}
108	
109	/* 背景の曲線スパイン（装飾） */
110	.spine { position: absolute; left: 0; right: 0; top: 92svh; bottom: 120px; z-index: 0; pointer-events: none; }
111	.spine__svg { display: block; width: 100%; height: 100%; overflow: visible; }
112	
113	/* ============================================
114	   hero-nav（TOPページ固定ヘッダー）
115	   ============================================ */
116	.hero-nav__veil {
117	  position: fixed; top: 0; left: 50%; transform: translateX(-50%);
118	  width: min(100%,375px); height: 88px; z-index: 89; pointer-events: none;
119	  backdrop-filter: blur(14px) saturate(150%); -webkit-backdrop-filter: blur(14px) saturate(150%);
120	  background: linear-gradient(180deg,rgba(244,251,254,0.72),rgba(244,251,254,0));
121	  -webkit-mask-image: linear-gradient(180deg,#000 0%,#000 58%,rgba(0,0,0,0) 100%);
122	  mask-image: linear-gradient(180deg,#000 0%,#000 58%,rgba(0,0,0,0) 100%);
123	}
124	.hero-nav {
125	  position: fixed; top: 0; left: 50%; transform: translateX(-50%);
126	  width: min(100%,375px); z-index: 90; display: flex; align-items: center;
127	  justify-content: space-between; padding: 22px clamp(18px,5cqw,48px);
128	  pointer-events: none;
129	}
130	.hero-nav__h1 { margin: 0; display: contents; }
131	.hero-nav__logo {
132	  pointer-events: auto; font-family: Jost, sans-serif; font-size: 13px; letter-spacing: 0.16em;
133	  color: #0E4257; transition: opacity .3s ease;
134	}
135	.hero-nav.is-open .hero-nav__logo { opacity: 0; pointer-events: none; }
136	.hero-nav__toggle {
137	  pointer-events: auto; width: 44px; height: 44px; display: flex; flex-direction: column;
138	  justify-content: center; align-items: flex-end; gap: 7px; background: none; border: none;
139	  cursor: pointer; padding: 0;
140	}
141	.hero-nav__bar {
142	  display: block; height: 2px; border-radius: 2px; background: #0E4257; width: 18px;
143	  transition: transform .4s cubic-bezier(.2,.7,.2,1), width .4s ease, background .3s ease;
144	}
145	.hero-nav__bar--top { width: 26px; }
146	.hero-nav.is-open .hero-nav__bar { background: #F4FBFE; }
147	.hero-nav.is-open .hero-nav__bar--top { transform: translateY(5px) rotate(14deg); }
148	.hero-nav.is-open .hero-nav__bar--bottom { width: 26px; transform: translateY(-5px) rotate(-14deg); }
149	
150	/* ============================================
151	   flow-rail（スクロール進行レール）
152	   ============================================ */
153	.flow-rail { position: fixed; bottom: 0; left: 50%; transform: translateX(-50%); width: min(100%,375px); height: 3px; z-index: 70; pointer-events: none; }
154	.flow-rail__track { position: absolute; inset: 0; background: rgba(79,195,232,0.22); }
155	.flow-rail__fill { position: absolute; left: 0; bottom: 0; height: 3px; width: 0%; background: linear-gradient(90deg,#4FC3E8,#FFC72C); border-radius: 3px; }
156	.flow-rail__rider { position: absolute; left: 17px; bottom: 7px; transform: translate(-50%,0); width: 30px; height: 30px; border-radius: 50%; background: #FFFFFF; box-shadow: 0 4px 16px rgba(16,72,95,0.22); display: flex; align-items: center; justify-content: center; }
157	.flow-rail__pulse { position: absolute; inset: 0; border-radius: 50%; background: rgba(255,199,44,0.45); animation: pulseRing 2.8s ease-out infinite; }
158	.flow-rail__icon { position: relative; width: 17px; height: 17px; }
159	
160	/* ============================================
161	   page-header（下層ページの戻るリンクヘッダー）
162	   ============================================ */
163	.page-header { padding: 24px clamp(20px,6cqw,80px); display: flex; justify-content: space-between; align-items: center; font-family: Archivo, sans-serif; font-size: 12px; letter-spacing: 0.16em; }
164	.page-header--dark { color: #8A8580; }
165	.page-header__back { display: inline-flex; align-items: center; gap: 10px; transition: gap .3s ease; }
166	.page-header__back:hover { gap: 18px; }
167	.page-header__label { color: #7B8DA6; }
168	
169	/* ============================================
170	   page-footer（下層ページ共通フッター）
171	   ============================================ */
172	.page-footer { padding: clamp(40px,5cqw,72px) clamp(20px,6cqw,80px); border-top: 1px solid #D3DEEB; display: flex; flex-wrap: wrap; gap: 16px; justify-content: space-between; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.16em; color: #7B8DA6; margin-top: auto; }
173	.page-footer--dark { border-top-color: #1E1D1D; color: #5A5652; }
174	
175	/* privacy は新デザインの配色・フォントに上書き（pianist・horrorの共有.shell/.page-header/.page-footerには影響させない） */
176	body.page-privacy .shell {
177	  background: #F4FBFE;
178	  box-shadow: 0 0 90px rgba(16,72,95,0.16);
179	}
180	body.page-privacy .page-header,
181	body.page-privacy .page-footer {
182	  font-family: Jost, sans-serif;
183	}
184	body.page-privacy .page-header__label,
185	body.page-privacy .page-footer {
186	  color: #4E9DBC;
187	}
188	body.page-privacy .page-footer {
189	  border-top-color: rgba(79,195,232,0.28);
190	}
191	
192	/* ============================================
193	   menu（ハンバーガーで開くサブメニュー）
194	   ============================================ */
195	.menu {
196	  position: fixed; top: 0; bottom: 0; left: 50%; transform: translateX(-50%);
197	  width: min(100%,375px); z-index: 80;
198	  background: linear-gradient(170deg,#0E4257,#0A3243 60%,#0E4257);
199	  display: flex; flex-direction: column; justify-content: flex-start; align-items: stretch;
200	  overflow-y: auto; -webkit-overflow-scrolling: touch;
201	  padding: 92px clamp(20px,6cqw,80px) 40px;
202	  transition: opacity .5s ease, visibility .5s ease, clip-path .7s cubic-bezier(.2,.7,.2,1);
203	  opacity: 0; visibility: hidden; clip-path: inset(0 0 100% 0); pointer-events: none;
204	}
205	.menu.is-open { opacity: 1; visibility: visible; clip-path: inset(0 0 0% 0); pointer-events: auto; }
206	.menu__inner { display: grid; gap: clamp(30px,6cqw,60px); width: 100%; }
207	.menu__group-title { font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.24em; color: #7FCBE4; margin: 0 0 20px; }
208	.menu__group-title--tight { margin-bottom: 18px; }
209	.menu__nav-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 12px; font-family: Jost, sans-serif; font-size: 16px; letter-spacing: 0.08em; color: #F4FBFE; }
210	.menu__social-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 14px; font-family: Jost, sans-serif; font-size: clamp(20px,3cqw,28px); color: #F4FBFE; }
211	.menu__social-link { display: inline-flex; align-items: center; gap: 12px; transition: transform .3s ease; }
212	.menu__social-link:hover { transform: translateX(10px); color: #7FCBE4; }
213	.menu__personal-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 18px; }
214	.menu__personal-link { display: block; }
215	.menu__personal-link-title { display: block; font-family: Jost, sans-serif; font-size: clamp(20px,3cqw,28px); color: #F4FBFE; transition: transform .3s ease; }
216	.menu__personal-link:hover .menu__personal-link-title { transform: translateX(10px); color: #FFD86B; }
217	.menu__personal-link-desc { display: block; font-size: 12px; color: #7FCBE4; margin-top: 4px; }
218	.menu__credit { margin: 36px 0 0; font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.2em; color: #4E9DBC; }
219	
220	/* ============================================
221	   PC表示（1000px以上）: 左に画像、右にメニューを配置し、
222	   モバイル用ヘッダー／ハンバーガーメニューは非表示にする
223	   ============================================ */
224	.pc-figure,
225	.pc-menu { display: none; }
226	
227	@media (min-width: 1000px) {
228	  .hero-nav,
229	  .hero-nav__veil,
230	  .menu { display: none; }
231	
232	  .pc-figure {
233	    display: flex;
234	    align-items: center;
235	    justify-content: center;
236	    position: fixed;
237	    top: 50%;
238	    left: 0;
239	    transform: translateY(-50%);
240	    width: calc(25% - 93.75px);
241	    height: 50vh;
242	    min-width: 120px;
243	    max-width: 210px;
244	    z-index: 40;
245	    background-image: repeating-linear-gradient(135deg,#E2EAF4 0 10px,#EDF2F8 10px 20px);
246	  }
247	  .pc-figure__label {
248	    font-family: ui-monospace,Menlo,monospace; font-size: 12px; letter-spacing: 0.16em;
249	    color: #7B8DA6; background: #F0F5FA; padding: 8px 16px; border: 1px solid #D3DEEB;
250	  }
251	
252	  .pc-menu {
253	    display: flex;
254	    flex-direction: column;
255	    justify-content: center;
256	    gap: clamp(28px,3vw,48px);
257	    position: fixed;
258	    top: 50%;
259	    right: 0;
260	    transform: translateY(-50%);
261	    width: calc(25% - 93.75px);
262	    height: 50vh;
263	    min-width: 120px;
264	    max-width: 210px;
265	    z-index: 40;
266	    padding: clamp(24px,3vw,48px) clamp(20px,3vw,32px);
267	    overflow-y: auto;
268	    background: linear-gradient(170deg,#0E4257,#0A3243 60%,#0E4257);
269	  }
270	  .pc-menu__logo { margin: 0; font-family: Jost, sans-serif; font-size: 14px; letter-spacing: 0.16em; color: #F4FBFE; }
271	  .pc-menu__nav-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 14px; font-family: Jost, sans-serif; font-size: 16px; letter-spacing: 0.06em; color: #F4FBFE; }
272	  .pc-menu__nav-list a,
273	  .pc-menu__social-list a,
274	  .pc-menu__personal-list a { transition: color .3s ease; }
275	  .pc-menu__nav-list a:hover,
276	  .pc-menu__social-list a:hover,
277	  .pc-menu__personal-list a:hover { color: #7FCBE4; }
278	  .pc-menu__group-title { margin: 0 0 14px; font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.24em; color: #7FCBE4; }
279	  .pc-menu__social-list,
280	  .pc-menu__personal-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; font-size: 13px; color: #F4FBFE; }
281	}
282	
283	/* ============================================
284	   hero（FIRST VIEW）
285	   ============================================ */
286	.hero { position: relative; min-height: 100svh; overflow: hidden; padding: clamp(104px,13cqw,150px) clamp(20px,6cqw,80px) clamp(64px,8cqw,90px); display: flex; flex-direction: column; justify-content: space-between; align-items: center; text-align: center; background: linear-gradient(170deg,#D7F0FA 0%,#BFE8F7 42%,#DCF2FA 78%,#F0FAFD 100%); }
287	.hero__blob { position: absolute; border-radius: 50%; pointer-events: none; }
288	.hero__blob--a { left: -14%; top: 6%; width: 210px; height: 210px; background: radial-gradient(circle at 34% 30%,rgba(255,255,255,0.85),rgba(255,255,255,0) 68%); }
289	.hero__blob--b { right: -22%; top: 34%; width: 250px; height: 250px; background: radial-gradient(circle at 60% 40%,rgba(255,222,130,0.34),rgba(255,222,130,0) 70%); }
290	.hero__meta { position: relative; display: flex; gap: 14px; align-items: center; justify-content: center; font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.24em; color: #4E9DBC; }
291	.hero__meta-line { width: 32px; height: 1px; background: #8FD3EA; }
292	.hero__heading { position: relative; margin: clamp(28px,6cqw,64px) 0 0; font-weight: 500; font-size: clamp(30px,8.4cqw,124px); line-height: 1.16; letter-spacing: -0.02em; color: #0E4257; text-wrap: balance; }
293	.hero__line { display: block; }
294	.hero__highlight { display: inline-block; background-image: linear-gradient(90deg,rgba(255,199,44,0.62),rgba(255,222,130,0.52)); background-repeat: no-repeat; background-size: 100% 0.22em; background-position: 0 88%; border-radius: 3px; }
295	.hero__foot { position: relative; display: flex; flex-direction: column; align-items: center; gap: clamp(22px,4cqw,56px); margin-top: clamp(32px,6cqw,80px); }
296	.hero__lead { margin: 0 auto; font-size: clamp(14px,1.5cqw,17px); line-height: 2; color: #2E7793; max-width: 34ch; }
297	.hero__signature { font-family: Jost, sans-serif; text-align: center; letter-spacing: 0.14em; }
298	.hero__signature-label { margin: 0; font-size: 11px; color: #4E9DBC; }
299	.hero__signature-name { margin: 6px 0 0; font-size: clamp(20px,2.4cqw,30px); color: #0E4257; }
300	.hero__scroll { position: relative; margin-top: clamp(28px,5cqw,56px); display: inline-flex; align-items: center; gap: 14px; font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.24em; color: #4E9DBC; width: fit-content; }
301	.hero__scroll-track { display: block; width: 64px; height: 1px; background: #A6DDEF; overflow: hidden; position: relative; }
302	.hero__scroll-bar { position: absolute; inset: 0; background: #F0B400; animation: scrollcue 2.4s ease-in-out infinite; }
303	.hero__wave { position: absolute; left: 0; right: 0; bottom: -1px; width: 100%; height: 90px; display: block; }
304	
305	/* ============================================
306	   float-badge（浮遊するアイコンバッジ／複数セクションで再利用）
307	   ============================================ */
308	.float-badge { position: absolute; border-radius: 50%; display: flex; align-items: center; justify-content: center; pointer-events: none; }
309	.float-badge--white { background: rgba(255,255,255,0.85); box-shadow: 0 8px 20px rgba(16,72,95,0.10); }
310	.float-badge--gold { background: rgba(255,199,44,0.16); }
311	.float-badge__icon { animation-timing-function: ease-in-out; animation-iteration-count: infinite; }
312	.float-badge__icon--a { animation-name: floatY; animation-duration: 5.5s; }
313	.float-badge__icon--b { animation-name: floatY2; animation-duration: 6.5s; }
314	.float-badge__icon--c { animation-name: floatY; animation-duration: 7s; }
315	
316	.hero__badge--connect { right: 18px; top: 20%; width: 44px; height: 44px; }
317	.hero__badge--connect .float-badge__icon { width: 19px; height: 19px; }
318	.hero__badge--organize { left: 30px; bottom: 38%; width: 46px; height: 46px; }
319	.hero__badge--organize .float-badge__icon { width: 20px; height: 20px; }
320	.hero__badge--schedule { right: 38px; bottom: 19%; width: 38px; height: 38px; }
321	.hero__badge--schedule .float-badge__icon { width: 17px; height: 17px; }
322	
323	/* ============================================
324	   about
325	   ============================================ */
326	.about__grid { display: grid; gap: clamp(30px,5cqw,72px); max-width: 1280px; margin: 0 auto; }
327	.about__intro { text-align: center; }
328	.about__meta { margin: clamp(32px,5cqw,64px) 0 0; display: grid; grid-template-columns: repeat(auto-fit,minmax(130px,1fr)); gap: 22px 28px; border-top: 1px solid rgba(79,195,232,0.28); padding-top: 26px; text-align: left; }
329	.about__meta-label { font-family: Jost, sans-serif; font-size: 10px; letter-spacing: 0.22em; color: #4E9DBC; }
330	.about__meta-value { margin: 8px 0 0; font-size: 15px; }
331	
332	/* ============================================
