538	.dream-stage__ear::before { content: ""; position: absolute; width: 48px; height: 82px; left: 31px; top: 42px; border: 3px solid #8A8580; border-radius: 50%; }
539	.dream-stage__ear-hole { position: absolute; left: 49px; top: 78px; width: 23px; height: 34px; border: 4px solid #9B2C22; border-radius: 50%; background: #050506; }
540	.dream-stage__ear-pulse { position: absolute; left: 35px; top: 65px; width: 50px; height: 58px; border: 1px solid #C1493B; border-radius: 50%; animation: earPulse 1.1s ease-in-out infinite; }
541	.dream-stage__insects { position: absolute; inset: 24px; color: #B9B0A9; opacity: 0; font: 24px/1 ui-monospace, monospace; }
542	.dream-stage__insects i { position: absolute; font-style: normal; }
543	.dream-stage__insects i:nth-child(1) { left: 14%; top: 18%; }.dream-stage__insects i:nth-child(2) { left: 76%; top: 20%; }.dream-stage__insects i:nth-child(3) { left: 21%; top: 70%; }.dream-stage__insects i:nth-child(4) { left: 68%; top: 74%; }.dream-stage__insects i:nth-child(5) { left: 44%; top: 10%; }.dream-stage__insects i:nth-child(6) { left: 85%; top: 51%; }.dream-stage__insects i:nth-child(7) { left: 6%; top: 48%; }.dream-stage__insects i:nth-child(8) { left: 48%; top: 86%; }
544	.dream-stage--still .dream-stage__ear { opacity: .08; transform: rotate(-17deg) scale(.82); }
545	.dream-stage--sound .dream-stage__ear-pulse { animation-duration: .38s; }
546	.dream-stage--nothing .dream-stage__ear { opacity: .04; transform: translateX(64px) rotate(-17deg); }
547	.dream-stage--nothing .dream-stage__caption { animation: flick 1.2s infinite; }
548	.dream-stage--inside .dream-stage__ear { transform: rotate(-17deg) scale(1.08); }
549	.dream-stage--inside .dream-stage__ear-hole { box-shadow: 0 0 22px 8px rgba(155,44,34,.36); }
550	.dream-stage--pull .dream-stage__ear { animation: earShake .16s ease-in-out infinite alternate; }
551	.dream-stage--pull .dream-stage__ear-pulse { animation-duration: .18s; }
552	.dream-stage--release .dream-stage__ear { opacity: .2; transform: rotate(-17deg) scale(.7); }
553	.dream-stage--release .dream-stage__insects { opacity: .8; animation: insectBurst 1.1s ease-out both; }
554	.dream-stage__caption { position: relative; margin: 0; color: #D6D2CB; font: 11px Archivo, sans-serif; letter-spacing: .22em; text-align: center; animation: flick 4s infinite; }
555	.dream-experience__copy { white-space: pre-line; min-height: 92px; margin: 28px 0 0; color: #B9B0A9; font-size: 14px; line-height: 2.1; }
556	.dream-experience__action { margin-top: 22px; border: 1px solid #4A2724; background: transparent; color: #D6D2CB; padding: 15px 18px; cursor: pointer; font: 11px Archivo, sans-serif; letter-spacing: .18em; transition: background .3s ease, border-color .3s ease; }
557	.dream-experience__action:hover { background: #9B2C22; border-color: #9B2C22; }
558	.dream-experience__progress { margin: 18px 0 0; color: #5A5652; font: 10px Archivo, sans-serif; letter-spacing: .2em; }
559	@keyframes dreamDrift { from { transform: translateX(0); } to { transform: translateX(48px); } }
560	@keyframes earPulse { 0%,100% { transform: scale(.8); opacity: .15; } 50% { transform: scale(1.2); opacity: .8; } }
561	@keyframes earShake { from { transform: rotate(-19deg) translateX(-4px); } to { transform: rotate(-14deg) translateX(4px); } }
562	@keyframes insectBurst { from { transform: scale(.2); opacity: 0; } 35% { opacity: .9; } to { transform: scale(1.25); opacity: .72; } }
563	@media (prefers-reduced-motion: reduce) { .dream-stage__sky, .dream-stage__ear-pulse { animation: none; } }
564	
