649	.pn-hero__photo { margin-top: clamp(34px,6cqw,64px); }
650	.pn-hero__lead { margin-top: clamp(32px,5cqw,56px); }
651	
652	/* --- PROFILE --- */
653	.pn-profile__aside { margin-top: clamp(34px,5cqw,56px); border-top: 1px solid #23211D; padding-top: 26px; display: grid; gap: 22px; }
654	.pn-profile__label { margin: 0 0 8px; font-family: Archivo, sans-serif; font-size: 10px; letter-spacing: 0.26em; color: #C9A34E; }
655	.pn-profile__item { margin: 0; font-family: "Zen Old Mincho", serif; font-size: 14px; line-height: 1.9; color: #F2EFE9; }
656	
657	/* --- AWARDS --- */
658	.pn-awards { list-style: none; margin: 0; padding: 0; display: grid; }
659	.pn-awards__item { display: grid; grid-template-columns: 54px 1fr; gap: 14px; padding: 18px 0; border-top: 1px solid #23211D; align-items: baseline; }
660	.pn-awards__item:last-child { border-bottom: 1px solid #23211D; }
661	.pn-awards__year { font-family: "Cormorant Garamond", Georgia, serif; font-size: 17px; color: #C9A34E; }
662	.pn-awards__text { font-family: "Zen Old Mincho", serif; font-size: 13.5px; line-height: 1.95; color: #C6C1B7; }
663	.pn-awards__text em { font-style: normal; color: #F2EFE9; }
664	
665	/* --- PERFORMANCE --- */
666	.pn-videos { display: grid; gap: clamp(26px,4cqw,44px); }
667	.pn-video__frame { position: relative; aspect-ratio: 16/9; border: 1px solid #23211D; background: #0E0E10; }
668	.pn-video__frame iframe { position: absolute; inset: 0; width: 100%; height: 100%; border: 0; }
669	.pn-video__cap { margin: 12px 0 0; display: flex; justify-content: space-between; gap: 14px; font-size: 12px; color: #8A8579; font-family: "Zen Old Mincho", serif; }
670	.pn-video__no { font-family: Archivo, sans-serif; font-size: 10px; letter-spacing: 0.2em; color: #C9A34E; }
671	
672	/* --- CONTACT / SNS --- */
673	.pn-contact__mail { display: inline-block; margin-top: 6px; font-family: "Cormorant Garamond", Georgia, serif; font-size: clamp(22px,5cqw,34px); letter-spacing: 0.03em; color: #E4C97E; border-bottom: 1px solid rgba(201,163,78,0.4); padding-bottom: 6px; }
674	.pn-sns { list-style: none; margin: clamp(34px,5cqw,52px) 0 0; padding: 0; display: grid; gap: 1px; background: #23211D; border: 1px solid #23211D; }
675	.pn-sns__link { display: flex; align-items: center; gap: 14px; background: #08080A; padding: 18px 20px; font-family: Archivo, sans-serif; font-size: 12px; letter-spacing: 0.18em; color: #F2EFE9; transition: background .35s ease, color .35s ease; }
676	.pn-sns__link:hover { background: #100E0A; color: #E4C97E; }
677	.pn-sns__icon { width: 16px; height: 16px; filter: brightness(0) invert(1); opacity: .8; }
678	.pn-sns__arrow { margin-left: auto; color: #6E6A61; }
