1	/* ============================================
2	   共通リセット
3	   ============================================ */
4	html { scroll-behavior: smooth; }
5	@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } * { animation: none !important; } }
6	* { box-sizing: border-box; }
7	body { margin: 0; font-family: "Zen Kaku Gothic New", "Archivo", system-ui, sans-serif; -webkit-font-smoothing: antialiased; }
8	a { color: inherit; text-decoration: none; }
9	
10	/* ページテーマ（body class="page-xxx"） */
11	/* page-portfolio（404）・page-privacy はTOPページと同じ新配色。page-pianist・page-horror は現行デザインを維持（別途リニューアル予定のため変更しない） */
12	body.page-portfolio { background: #EAF6FB; color: #10485F; }
13	body.page-privacy { background: #EAF6FB; color: #10485F; }
14	body.page-pianist { background: #08080A; color: #F2EFE9; }
15	body:has(.pn-shell) {
16	  color: #F2EFE9;
17	  background: linear-gradient(180deg,rgba(8,8,10,0.4),rgba(8,8,10,0.65)), url("images/25253200_l.webp") center / cover no-repeat fixed, #08080A;
18	}
19	body:has(.top-shell) {
20	  background: url("images/26388934.webp") center / cover no-repeat fixed;
21	}
22	body.page-portfolio a:hover { color: #B57E00; }
23	body.page-privacy a:hover { color: #B57E00; }
24	body.page-pianist a:hover { color: #E4C97E; }
25	.pn-shell a:hover { color: #E4C97E; }
26	body.page-portfolio ::selection,
27	body.page-privacy ::selection { background: #FFE79A; color: #10485F; }
28	
29	body.page-horror { background: #07070A; color: #D6D2CB; }
30	body.page-horror a:hover { color: #9B2C22; }
31	
32	/* ============================================
33	   キーフレームアニメーション
34	   ============================================ */
35	@keyframes scrollcue { 0% { transform: translateY(-100%); } 100% { transform: translateY(100%); } }
36	@keyframes fadeup { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: none; } }
37	@keyframes flick { 0%,100% { opacity: .85; } 47% { opacity: .85; } 48% { opacity: .35; } 52% { opacity: .9; } 70% { opacity: .6; } }
38	@keyframes slowfade { from { opacity: 0; } to { opacity: 1; } }
39	@keyframes floatY { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-9px); } }
40	@keyframes floatY2 { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-14px); } }
41	@keyframes sway { 0%,100% { transform: translateX(0); } 50% { transform: translateX(-40px); } }
42	@keyframes nodeGlow { 0%,100% { box-shadow: 0 0 0 0 rgba(255,199,44,0); } 50% { box-shadow: 0 0 0 7px rgba(255,199,44,0.16); } }
43	@keyframes pulseRing { 0% { transform: scale(1); opacity: .55; } 70% { transform: scale(2.1); opacity: 0; } 100% { transform: scale(2.1); opacity: 0; } }
44	
45	/* ============================================
46	   共通ユーティリティ（複数ブロックで使い回すパーツ）
47	   ============================================ */
48	.container { max-width: 1280px; margin: 0 auto; }
49	.sub-container { max-width: 1180px; margin: 0 auto; }
50	.text-block { margin: 0; }
51	
52	.eyebrow { font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.26em; color: #B57E00; margin: 0 0 28px; }
53	.eyebrow--tight { margin-bottom: 24px; }
54	
55	.section { position: relative; padding: clamp(56px,8cqw,130px) clamp(20px,6cqw,80px) clamp(64px,9cqw,130px); }
56	.section--first { min-height: 100svh; padding: clamp(104px,13cqw,150px) clamp(20px,6cqw,80px) clamp(64px,8cqw,90px); overflow: hidden; }
57	.section--about { padding-top: clamp(72px,10cqw,150px); padding-bottom: clamp(56px,8cqw,120px); }
58	.section--works { padding-top: clamp(48px,7cqw,120px); }
59	.section--next { overflow: hidden; }
60	.section--contact { padding: clamp(64px,10cqw,160px) clamp(20px,6cqw,80px) clamp(72px,10cqw,160px); }
61	.section__head { display: flex; flex-direction: column; align-items: center; text-align: center; gap: 14px; margin-bottom: clamp(36px,6cqw,80px); }
62	.section__eyebrow { font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.26em; color: #B57E00; margin: 0; }
63	.section__heading { margin: 0; font-weight: 500; font-size: clamp(23px,3.6cqw,46px); line-height: 1.55; letter-spacing: -0.01em; color: #0E4257; }
64	.section__intro { text-align: center; }
65	
66	.wave-divider { line-height: 0; position: relative; }
67	.wave-divider--to-dark { background: linear-gradient(180deg,#2A97C4,#0E4257); }
68	.wave-divider__svg { display: block; width: 100%; height: clamp(44px,7cqw,84px); }
69	.wave-divider__badge { position: absolute; left: 50%; top: 50%; margin-left: -17px; margin-top: -17px; width: 34px; height: 34px; }
70	.wave-divider__badge .float-badge__icon { width: 18px; height: 18px; }
71	
72	/* ============================================
73	   shell（各ページ共通の外枠カード）
74	   ============================================ */
75	.shell {
76	  container-type: inline-size;
77	  max-width: 375px;
78	  margin: 0 auto;
79	  min-height: 100svh;
80	  position: relative;
81	  overflow-x: hidden;
82	  display: flex;
83	  flex-direction: column;
84	  background: #F5F8FC;
85	  box-shadow: 0 0 80px rgba(18,36,63,0.16);
86	}
87	.shell--muted { background: #F0F5FA; }
88	.shell--dark { background: #0B0B0C; box-shadow: 0 0 80px rgba(0,0,0,0.5); }
89	
90	.skip-link { position: absolute; left: -9999px; top: 0; background: #12243F; color: #F5F8FC; padding: 12px 18px; z-index: 200; }
91	.skip-link:focus { left: 12px; top: 12px; }
92	
93	/* ============================================
94	   top-shell（TOPページ専用の外枠カード。.shellは他ページ共有のため触らずこちらを使う）
95	   ============================================ */
96	.top-shell {
97	  container-type: inline-size;
98	  max-width: 375px;
99	  margin: 0 auto;
100	  min-height: 100svh;
101	  position: relative;
102	  overflow-x: clip;
103	  display: flex;
104	  flex-direction: column;
105	  background: linear-gradient(180deg,#F4FBFE 0%,#EAF7FC 14%,#DCF1F9 34%,#E9F7FC 52%,#DDF2F9 72%,#F1FAFD 100%);
106	  box-shadow: 0 0 90px rgba(16,72,95,0.16);
107	}
108	
109	/* 背景の曲線スパイン（装飾） */
110	.spine { position: absolute; left: 0; right: 0; top: 92svh; bottom: 120px; z-index: 0; pointer-events: none; }
111	.spine__svg { display: block; width: 100%; height: 100%; overflow: visible; }
112	
113	/* ============================================
114	   hero-nav（TOPページ固定ヘッダー）
115	   ============================================ */
116	.hero-nav__veil {
117	  position: fixed; top: 0; left: 50%; transform: translateX(-50%);
118	  width: min(100%,375px); height: 88px; z-index: 89; pointer-events: none;
119	  backdrop-filter: blur(14px) saturate(150%); -webkit-backdrop-filter: blur(14px) saturate(150%);
120	  background: linear-gradient(180deg,rgba(244,251,254,0.72),rgba(244,251,254,0));
121	  -webkit-mask-image: linear-gradient(180deg,#000 0%,#000 58%,rgba(0,0,0,0) 100%);
122	  mask-image: linear-gradient(180deg,#000 0%,#000 58%,rgba(0,0,0,0) 100%);
123	}
124	.hero-nav {
125	  position: fixed; top: 0; left: 50%; transform: translateX(-50%);
126	  width: min(100%,375px); z-index: 90; display: flex; align-items: center;
127	  justify-content: space-between; padding: 22px clamp(18px,5cqw,48px);
128	  pointer-events: none;
129	}
130	.hero-nav__h1 { margin: 0; display: contents; }
131	.hero-nav__logo {
132	  pointer-events: auto; font-family: Jost, sans-serif; font-size: 13px; letter-spacing: 0.16em;
133	  color: #0E4257; transition: opacity .3s ease;
134	}
135	.hero-nav.is-open .hero-nav__logo { opacity: 0; pointer-events: none; }
136	.hero-nav__toggle {
137	  pointer-events: auto; width: 44px; height: 44px; display: flex; flex-direction: column;
138	  justify-content: center; align-items: flex-end; gap: 7px; background: none; border: none;
139	  cursor: pointer; padding: 0;
140	}
141	.hero-nav__bar {
142	  display: block; height: 2px; border-radius: 2px; background: #0E4257; width: 18px;
143	  transition: transform .4s cubic-bezier(.2,.7,.2,1), width .4s ease, background .3s ease;
144	}
145	.hero-nav__bar--top { width: 26px; }
146	.hero-nav.is-open .hero-nav__bar { background: #F4FBFE; }
147	.hero-nav.is-open .hero-nav__bar--top { transform: translateY(5px) rotate(14deg); }
148	.hero-nav.is-open .hero-nav__bar--bottom { width: 26px; transform: translateY(-5px) rotate(-14deg); }
149	
150	/* ============================================
151	   flow-rail（スクロール進行レール）
152	   ============================================ */
153	.flow-rail { position: fixed; bottom: 0; left: 50%; transform: translateX(-50%); width: min(100%,375px); height: 3px; z-index: 70; pointer-events: none; }
154	.flow-rail__track { position: absolute; inset: 0; background: rgba(79,195,232,0.22); }
155	.flow-rail__fill { position: absolute; left: 0; bottom: 0; height: 3px; width: 0%; background: linear-gradient(90deg,#4FC3E8,#FFC72C); border-radius: 3px; }
156	.flow-rail__rider { position: absolute; left: 17px; bottom: 7px; transform: translate(-50%,0); width: 30px; height: 30px; border-radius: 50%; background: #FFFFFF; box-shadow: 0 4px 16px rgba(16,72,95,0.22); display: flex; align-items: center; justify-content: center; }
157	.flow-rail__pulse { position: absolute; inset: 0; border-radius: 50%; background: rgba(255,199,44,0.45); animation: pulseRing 2.8s ease-out infinite; }
158	.flow-rail__icon { position: relative; width: 17px; height: 17px; }
159	
160	/* ============================================
161	   page-header（下層ページの戻るリンクヘッダー）
162	   ============================================ */
163	.page-header { padding: 24px clamp(20px,6cqw,80px); display: flex; justify-content: space-between; align-items: center; font-family: Archivo, sans-serif; font-size: 12px; letter-spacing: 0.16em; }
164	.page-header--dark { color: #8A8580; }
165	.page-header__back { display: inline-flex; align-items: center; gap: 10px; transition: gap .3s ease; }
166	.page-header__back:hover { gap: 18px; }
167	.page-header__label { color: #7B8DA6; }
168	
169	/* ============================================
