/* ============================================
   共通リセット
   ============================================ */
html { scroll-behavior: smooth; }
@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } * { animation: none !important; } }
* { box-sizing: border-box; }
body { margin: 0; font-family: "Zen Kaku Gothic New", "Archivo", system-ui, sans-serif; -webkit-font-smoothing: antialiased; }
a { color: inherit; text-decoration: none; }

/* ページテーマ（body class="page-xxx"） */
/* page-portfolio（404）・page-privacy はTOPページと同じネイビー×オレンジ配色。page-pianist・page-horror は現行デザインを維持（別途リニューアル予定のため変更しない） */
body.page-portfolio { background: #FFFFFF; color: #172E4A; }
body.page-privacy { background: #FFFFFF; color: #172E4A; }
body.page-pianist { background: #08080A; color: #F2EFE9; }
body:has(.pn-shell) {
  color: #F2EFE9;
  background: linear-gradient(180deg,rgba(8,8,10,0.4),rgba(8,8,10,0.65)), url("images/25253200_l.webp") center / cover no-repeat fixed, #08080A;
}
body:has(.top-shell) {
  background: #FFFFFF;
}
body.page-portfolio a:hover { color: #DC8541; }
body.page-privacy a:hover { color: #DC8541; }
body.page-pianist a:hover { color: #E4C97E; }
.pn-shell a:hover { color: #E4C97E; }
body.page-portfolio ::selection,
body.page-privacy ::selection { background: #F6D3B0; color: #172E4A; }

body.page-horror { background: #07070A; color: #D6D2CB; }
body.page-horror a:hover { color: #9B2C22; }

/* ============================================
   キーフレームアニメーション
   ============================================ */
@keyframes fadeup { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: none; } }
@keyframes flick { 0%,100% { opacity: .85; } 47% { opacity: .85; } 48% { opacity: .35; } 52% { opacity: .9; } 70% { opacity: .6; } }

/* ============================================
   共通ユーティリティ
   ============================================ */
.container { max-width: 1180px; margin: 0 auto; padding-inline: clamp(20px,5vw,64px); }

.tag-row { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 10px; }
.tag { display: inline-flex; align-items: center; font-size: 12px; letter-spacing: 0.01em; color: #3E4A5C; border: 1px solid #D8DCE3; border-radius: 999px; padding: 7px 15px; background: #FFFFFF; white-space: nowrap; }
.tag--onDark { color: #EAF0F6; border-color: rgba(234,240,246,0.32); background: rgba(255,255,255,0.06); }

.btn-group { display: flex; flex-wrap: wrap; gap: 14px; align-items: center; }
.btn { display: inline-flex; align-items: center; justify-content: center; gap: 10px; font-family: Jost, sans-serif; font-size: 13px; letter-spacing: 0.1em; padding: 16px 30px; border-radius: 999px; border: 1.5px solid transparent; cursor: pointer; transition: background .25s ease, border-color .25s ease, color .25s ease, transform .15s ease; white-space: nowrap; }
.btn:hover { transform: translateY(-1px); }
.btn--primary { background: #DC8541; color: #FFFFFF; font-weight: 600; }
.btn--primary:hover { background: #C06E2E; }
.btn--secondary { background: transparent; color: #172E4A; border-color: #172E4A; }
.btn--secondary:hover { background: #172E4A; color: #FFFFFF; }
.btn--onDark { background: transparent; color: #FFFFFF; border-color: rgba(255,255,255,0.5); }
.btn--onDark:hover { background: rgba(255,255,255,0.12); border-color: #FFFFFF; }
.btn--sm { padding: 11px 20px; font-size: 12px; }

/* ============================================
   shell（各ページ共通の外枠カード／pianist・horror・privacyと共有のため触らない）
   ============================================ */
.shell {
  container-type: inline-size;
  max-width: 375px;
  margin: 0 auto;
  min-height: 100svh;
  position: relative;
  overflow-x: hidden;
  display: flex;
  flex-direction: column;
  background: #F5F8FC;
  box-shadow: 0 0 80px rgba(18,36,63,0.16);
}
.shell--muted { background: #F0F5FA; }
.shell--dark { background: #0B0B0C; box-shadow: 0 0 80px rgba(0,0,0,0.5); }

.skip-link { position: absolute; left: -9999px; top: 0; background: #12243F; color: #F5F8FC; padding: 12px 18px; z-index: 200; }
.skip-link:focus { left: 12px; top: 12px; }

/* ============================================
   page-header（下層ページの戻るリンクヘッダー／pianist・horror・privacyと共有のため触らない）
   ============================================ */
.page-header { padding: 24px clamp(20px,6cqw,80px); display: flex; justify-content: space-between; align-items: center; font-family: Archivo, sans-serif; font-size: 12px; letter-spacing: 0.16em; }
.page-header--dark { color: #8A8580; }
.page-header__back { display: inline-flex; align-items: center; gap: 10px; transition: gap .3s ease; }
.page-header__back:hover { gap: 18px; }
.page-header__label { color: #7B8DA6; }

/* ============================================
   page-footer（下層ページ共通フッター／pianist・horror・privacyと共有のため触らない）
   ============================================ */
.page-footer { padding: clamp(40px,5cqw,72px) clamp(20px,6cqw,80px); border-top: 1px solid #D3DEEB; display: flex; flex-wrap: wrap; gap: 16px; justify-content: space-between; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.16em; color: #7B8DA6; margin-top: auto; }
.page-footer--dark { border-top-color: #1E1D1D; color: #5A5652; }

/* privacy は新デザイン（ネイビー×オレンジ）に上書き（pianist・horrorの共有.shell/.page-header/.page-footerには影響させない） */
body.page-privacy .shell {
  background: #FFFFFF;
  box-shadow: 0 0 90px rgba(23,46,74,0.10);
}
body.page-privacy .page-header,
body.page-privacy .page-footer {
  font-family: Jost, sans-serif;
}
body.page-privacy .page-header__label,
body.page-privacy .page-footer {
  color: #7C8798;
}
body.page-privacy .page-footer {
  border-top-color: #E3E6EB;
}

/* ============================================
   top-shell（TOPページのラッパー／固定フレームは使わずフル幅レスポンシブ）
   ============================================ */
.top-shell {
  min-height: 100svh;
  display: flex;
  flex-direction: column;
}

/* ============================================
   site-header（TOPページ固定ヘッダー／DCコンポーネントの状態クラス hero-nav / menu は名称を維持）
   ============================================ */
.hero-nav {
  position: sticky; top: 0; z-index: 90;
  display: flex; align-items: center; justify-content: space-between;
  gap: 20px;
  padding: 18px clamp(20px,5vw,64px);
  background: rgba(255,255,255,0.96);
  border-bottom: 1px solid #E3E6EB;
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}
.hero-nav__h1 { margin: 0; }
.hero-nav__logo { display: inline-flex; flex-direction: column; gap: 2px; line-height: 1; }
.hero-nav__logo-main { font-family: Jost, sans-serif; font-size: 17px; letter-spacing: 0.08em; color: #172E4A; font-weight: 500; }
.hero-nav__logo-sub { font-family: Jost, sans-serif; font-size: 9px; letter-spacing: 0.24em; color: #DC8541; }

.hero-nav__nav { display: none; }
.hero-nav__nav-list { list-style: none; margin: 0; padding: 0; display: flex; align-items: center; gap: clamp(18px,2.4vw,34px); font-size: 14px; color: #3E4A5C; }
.hero-nav__nav-list a { transition: color .2s ease; }
.hero-nav__nav-list a:hover { color: #DC8541; }
.hero-nav__actions { display: flex; align-items: center; gap: 22px; }

.hero-nav__toggle {
  width: 40px; height: 40px; display: flex; flex-direction: column;
  justify-content: center; align-items: center; gap: 6px; background: none; border: none;
  cursor: pointer; padding: 0; flex: none;
}
.hero-nav__bar {
  display: block; height: 2px; width: 22px; border-radius: 2px; background: #172E4A;
  transition: transform .35s cubic-bezier(.2,.7,.2,1), opacity .2s ease;
}
.hero-nav.is-open .hero-nav__bar--top { transform: translateY(4px) rotate(45deg); }
.hero-nav.is-open .hero-nav__bar--bottom { transform: translateY(-4px) rotate(-45deg); }

@media (min-width: 880px) {
  .hero-nav__nav { display: block; }
  .hero-nav__toggle { display: none; }
}
@media (max-width: 879px) {
  .hero-nav__actions .btn { display: none; }
}

/* ============================================
   menu（ハンバーガーで開くフルスクリーンナビ／DCコンポーネントの状態クラス menu は名称を維持）
   ============================================ */
.menu {
  position: fixed; inset: 0; z-index: 95;
  background: #172E4A;
  display: flex; flex-direction: column;
  overflow-y: auto; -webkit-overflow-scrolling: touch;
  padding: 96px clamp(24px,7vw,64px) 48px;
  transition: opacity .4s ease, visibility .4s ease;
  opacity: 0; visibility: hidden; pointer-events: none;
}
.menu.is-open { opacity: 1; visibility: visible; pointer-events: auto; }
.menu__cta { margin-bottom: clamp(32px,6vw,56px); }
.menu__inner { display: grid; gap: clamp(30px,6vw,56px); width: 100%; max-width: 420px; }
.menu__group-title { font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.24em; color: #7FA0C4; margin: 0 0 18px; }
.menu__nav-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 14px; font-family: Jost, sans-serif; font-size: 19px; letter-spacing: 0.04em; color: #FFFFFF; }
.menu__social-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 12px; font-size: 14px; color: #FFFFFF; }
.menu__social-link { display: inline-flex; align-items: center; gap: 12px; transition: transform .3s ease; }
.menu__social-link:hover { transform: translateX(8px); color: #DC8541; }
.menu__personal-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 16px; }
.menu__personal-link { display: block; }
.menu__personal-link-title { display: block; font-size: 15px; color: #FFFFFF; transition: transform .3s ease; }
.menu__personal-link:hover .menu__personal-link-title { transform: translateX(8px); color: #DC8541; }
.menu__personal-link-desc { display: block; font-size: 12px; color: #7FA0C4; margin-top: 4px; }
.menu__credit { margin: 36px 0 0; font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.16em; color: #4C6689; }

@media (min-width: 880px) {
  .menu { display: none; }
}

/* ============================================
   section 基本パターン
   ============================================ */
.section { position: relative; padding-block: clamp(64px,9vw,120px); background: #FFFFFF; }
.section--alt { background: #F6F7F9; }
.section--dark { background: #172E4A; color: #EAF0F6; }
.section--tight { padding-block: clamp(40px,6vw,80px); }

.section__head { max-width: 640px; margin-bottom: clamp(32px,5vw,64px); }
.section__head--center { margin-inline: auto; text-align: center; }
.section__eyebrow { display: block; font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.24em; text-transform: uppercase; color: #DC8541; margin: 0 0 14px; }
.section__heading { margin: 0; font-weight: 500; font-size: clamp(24px,3.2vw,38px); line-height: 1.5; letter-spacing: -0.01em; color: #172E4A; }
.section--dark .section__heading { color: #FFFFFF; }
.section__lead { margin: 18px 0 0; font-size: 15px; line-height: 1.95; color: #56637A; }
.section--dark .section__lead { color: #C3D0E0; }

/* ============================================
   hero
   ============================================ */
.hero { padding-top: clamp(56px,9vw,96px); padding-bottom: clamp(56px,9vw,96px); background: #FFFFFF; overflow: hidden; }
.hero__inner { display: grid; gap: clamp(40px,6vw,64px); align-items: center; }
.hero__eyebrow { display: flex; align-items: center; gap: 14px; font-family: Jost, sans-serif; font-size: 12px; letter-spacing: 0.22em; color: #56637A; margin: 0 0 clamp(20px,3vw,28px); }
.hero__eyebrow-line { width: 32px; height: 1px; background: #D8DCE3; }
.hero__heading { margin: 0; font-weight: 500; font-size: clamp(30px,5.2vw,52px); line-height: 1.4; letter-spacing: -0.01em; color: #172E4A; }
.hero__line { display: block; }
.hero__highlight { color: #DC8541; }
.hero__lead { margin: clamp(22px,3vw,32px) 0 0; font-size: 15px; line-height: 2; color: #56637A; max-width: 46ch; }
.hero__tags { margin-top: clamp(22px,3vw,32px); }
.hero__actions { margin-top: clamp(28px,4vw,40px); }

.hero__visual { position: relative; }
.hero__photo {
  width: 100%; max-width: 360px; margin: 0 auto; aspect-ratio: 4/5;
  border: 1px solid #D8DCE3; border-radius: 12px;
  background-image: repeating-linear-gradient(135deg,#F1F3F6 0 10px,#F8F9FA 10px 20px);
  display: flex; align-items: center; justify-content: center;
}
.hero__photo-label { font-family: ui-monospace,Menlo,monospace; font-size: 11px; letter-spacing: 0.16em; color: #8A93A3; background: #FFFFFF; padding: 6px 14px; border: 1px solid #E3E6EB; border-radius: 999px; }

@media (min-width: 860px) {
  .hero__inner { grid-template-columns: minmax(0,1fr) 320px; }
  .hero__visual { order: 2; }
}

/* ============================================
   tile-grid（PROBLEMS / TEAM / WORK STYLE 共通）
   ============================================ */
.tile-grid { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(2,1fr); gap: 14px; }
.tile { display: flex; flex-direction: column; align-items: center; gap: 14px; text-align: center; background: #FFFFFF; border: 1px solid #E3E6EB; border-radius: 10px; padding: clamp(22px,3vw,30px) 16px; }
.section--alt .tile { background: #FFFFFF; }
.tile__icon { display: flex; align-items: center; justify-content: center; width: 48px; height: 48px; border-radius: 50%; background: #F6F7F9; }
.tile__icon img { width: 24px; height: 24px; }
.tile__text { margin: 0; font-size: 14px; line-height: 1.75; color: #172E4A; font-weight: 500; }
.tile__label { font-size: 13px; font-weight: 500; color: #172E4A; }

@media (min-width: 640px) {
  .tile-grid--3 { grid-template-columns: repeat(3,1fr); }
}
@media (min-width: 880px) {
  .tile-grid--6 { grid-template-columns: repeat(6,1fr); }
  .tile-grid--3 { grid-template-columns: repeat(3,1fr); }
}

/* ============================================
   timeline（SCOPE / PROFILE経歴 共通）
   ============================================ */
.timeline { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; }
.timeline__item { display: flex; align-items: center; gap: 16px; padding: 18px 2px; border-bottom: 1px solid #E3E6EB; }
.timeline__item:first-child { padding-top: 0; }
.timeline__marker { flex: none; width: 38px; height: 38px; border-radius: 50%; display: flex; align-items: center; justify-content: center; }
.timeline__marker img { width: 18px; height: 18px; }
.timeline__marker { border: 1.5px solid #C7CEDA; background: #FFFFFF; }
.timeline__item--covered .timeline__marker { border-color: #172E4A; background: #172E4A; }
.timeline__item--covered .timeline__marker img { filter: brightness(0) invert(1); }
.timeline__body { flex: 1; display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 10px; }
.timeline__no { font-family: Jost, sans-serif; font-size: 11px; color: #A7AFBC; min-width: 20px; }
.timeline__label { font-size: 15px; font-weight: 500; color: #172E4A; }
.timeline__badge { font-size: 11px; letter-spacing: 0.04em; color: #A7AFBC; }
.timeline__item--covered .timeline__badge { color: #DC8541; font-weight: 600; }

@media (min-width: 900px) {
  .timeline--scope { flex-direction: row; flex-wrap: wrap; position: relative; padding-top: 24px; }
  .timeline--scope::before { content: ""; position: absolute; top: 43px; left: 0; right: 0; height: 1px; background: #E3E6EB; }
  .timeline--scope .timeline__item { flex: 1 1 0; min-width: 96px; flex-direction: column; align-items: center; text-align: center; gap: 10px; border-bottom: none; padding: 0 4px; position: relative; }
  .timeline--scope .timeline__marker { position: relative; z-index: 1; }
  .timeline--scope .timeline__body { flex-direction: column; align-items: center; gap: 4px; }
}

/* ============================================
   philosophy（PHILOSOPHY）
   ============================================ */
.chain { display: flex; flex-direction: column; align-items: stretch; gap: 4px; max-width: 900px; margin: 0 auto; }
.chain__node { background: #FFFFFF; color: #172E4A; border-radius: 10px; padding: clamp(22px,3vw,30px) clamp(20px,3vw,28px); text-align: center; flex: 1; }
.chain__node--accent { box-shadow: inset 0 3px 0 #DC8541; }
.chain__role { margin: 0; font-family: Jost, sans-serif; font-weight: 600; font-size: 13px; letter-spacing: 0.08em; color: #172E4A; }
.chain__points { list-style: none; margin: 16px 0 0; padding: 0; display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; }
.chain__points .tag { font-size: 11px; padding: 6px 12px; }
.chain__arrow { align-self: center; color: #DC8541; font-size: 18px; line-height: 1; padding: 6px 0; transform: rotate(90deg); }

.philosophy__points { list-style: none; margin: 20px 0 0; padding: 0; display: grid; gap: 10px; max-width: 40ch; }
.philosophy__points li { font-size: 14px; color: #FFFFFF; padding-left: 20px; position: relative; }
.philosophy__points li::before { content: "―"; position: absolute; left: 0; color: #DC8541; }

@media (min-width: 820px) {
  .chain { flex-direction: row; align-items: stretch; }
  .chain__arrow { transform: none; }
}

/* ============================================
   work-card（WORKS）
   ============================================ */
.work-grid { display: grid; grid-template-columns: 1fr; gap: 28px; }
.work-card { display: flex; flex-direction: column; background: #FFFFFF; border: 1px solid #E3E6EB; border-radius: 10px; overflow: hidden; }
.work-card__media { aspect-ratio: 4/3; background: #F6F7F9; overflow: hidden; }
.work-card__media img { display: block; width: 100%; height: 100%; object-fit: cover; }
.work-card__media--placeholder { display: flex; align-items: center; justify-content: center; background-image: repeating-linear-gradient(135deg,#F1F3F6 0 10px,#F8F9FA 10px 20px); }
.work-card__media--placeholder span { font-family: ui-monospace,Menlo,monospace; font-size: 11px; letter-spacing: 0.14em; color: #8A93A3; background: #FFFFFF; padding: 6px 12px; border: 1px solid #E3E6EB; border-radius: 999px; }
.work-card__body { padding: 24px clamp(20px,3vw,28px) clamp(24px,3vw,28px); display: flex; flex-direction: column; gap: 18px; }
.work-card__no { margin: 0; font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.2em; color: #DC8541; }
.work-card__title { margin: 8px 0 0; font-weight: 500; font-size: 19px; color: #172E4A; }
.work-card__field-label { margin: 0 0 8px; font-family: Jost, sans-serif; font-size: 10px; letter-spacing: 0.18em; color: #A7AFBC; text-transform: uppercase; }
.work-card__roles { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 8px; }
.work-card__role { font-size: 12px; color: #3E4A5C; border: 1px solid #D8DCE3; border-radius: 999px; padding: 5px 12px; white-space: nowrap; }
.work-card__text { margin: 0; font-size: 13px; line-height: 1.9; color: #56637A; }
.work-card__result { margin: 0; padding-left: 14px; border-left: 3px solid #DC8541; font-size: 13px; font-weight: 700; color: #172E4A; line-height: 1.7; }

@media (min-width: 720px) {
  .work-grid { grid-template-columns: repeat(auto-fit,minmax(280px,1fr)); }
}

/* ============================================
   process-row（DIRECTION SAMPLE）
   ============================================ */
.process-row { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; align-items: flex-start; gap: 4px 0; }
.process-row__item { display: flex; flex-direction: column; align-items: center; gap: 8px; width: 96px; }
.process-row__icon { display: flex; align-items: center; justify-content: center; width: 44px; height: 44px; border-radius: 50%; background: #F6F7F9; border: 1px solid #E3E6EB; }
.process-row__icon img { width: 22px; height: 22px; }
.process-row__label { font-size: 12px; line-height: 1.6; color: #3E4A5C; text-align: center; }
.process-row__arrow { color: #C7CEDA; font-size: 14px; align-self: center; margin-top: 20px; padding: 0 2px; }

/* ============================================
   profile（PROFILE）
   ============================================ */
.profile__top { display: flex; flex-direction: column; align-items: center; gap: 20px; text-align: center; margin-bottom: clamp(40px,6vw,64px); }
.profile__photo { width: 152px; height: 190px; border-radius: 12px; background-image: repeating-linear-gradient(135deg,#F1F3F6 0 10px,#F8F9FA 10px 20px); border: 1px solid #E3E6EB; display: flex; align-items: center; justify-content: center; }
.profile__photo-label { font-family: ui-monospace,Menlo,monospace; font-size: 10px; letter-spacing: 0.14em; color: #8A93A3; background: #FFFFFF; padding: 5px 10px; border-radius: 999px; }
.profile__name { margin: 0; font-weight: 500; font-size: clamp(21px,2.6vw,28px); color: #172E4A; }
.profile__name-en { display: block; margin-top: 4px; font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.2em; color: #A7AFBC; }
.profile__role { margin: 0; font-size: 13px; color: #56637A; }

.stat-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 16px 12px; margin-top: clamp(36px,5vw,56px); border-top: 1px solid #E3E6EB; padding-top: 24px; }
.stat__label { margin: 0; font-family: Jost, sans-serif; font-size: 10px; letter-spacing: 0.14em; color: #A7AFBC; }
.stat__value { margin: 8px 0 0; font-size: 13px; line-height: 1.7; color: #172E4A; }

.pull-quote { margin: clamp(36px,5vw,56px) 0 0; padding-left: 20px; border-left: 3px solid #DC8541; font-size: clamp(16px,1.8vw,19px); font-weight: 500; line-height: 1.9; color: #172E4A; max-width: 32ch; }

/* ============================================
   cta-dark（最終CTA）
   ============================================ */
.section--cta { background: #172E4A; color: #FFFFFF; text-align: center; }
.cta__bubbles { justify-content: center; margin-top: clamp(28px,4vw,40px); }
.cta__bubbles .tag { color: #EAF0F6; border-color: rgba(255,255,255,0.28); background: rgba(255,255,255,0.06); }
.cta__body { margin: clamp(24px,4vw,36px) auto 0; max-width: 46ch; font-size: 15px; line-height: 2.05; color: #C3D0E0; }
.cta__actions { margin-top: clamp(32px,5vw,48px); display: flex; flex-direction: column; align-items: center; gap: 16px; }
.cta__email { font-family: Jost, sans-serif; font-size: 14px; letter-spacing: 0.04em; color: #FFFFFF; border-bottom: 1px solid rgba(255,255,255,0.4); padding-bottom: 2px; }
.cta__note { margin: 0; font-size: 11px; letter-spacing: 0.1em; color: #7FA0C4; }

/* ============================================
   contact + form
   ============================================ */
.contact__lead { max-width: 46ch; margin: 0 0 clamp(32px,5vw,48px); font-size: 14px; line-height: 1.95; color: #56637A; }
.contact__frame { display: none; width: 0; height: 0; border: 0; }

.form { max-width: 640px; border-top: 1px solid #E3E6EB; padding-top: clamp(28px,4vw,40px); }
.form.is-sent { display: none; }
.form__eyebrow { margin: 0 0 24px; font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.2em; color: #A7AFBC; }
.form__fields { display: grid; gap: 22px; }
.form__field { display: grid; gap: 8px; }
.form__label { font-size: 13px; font-weight: 500; color: #172E4A; }
.form__required { color: #DC8541; }
.form__input { width: 100%; font: inherit; font-size: 16px; color: #172E4A; background: transparent; border: none; border-bottom: 1px solid #D8DCE3; padding: 10px 0; outline: none; transition: border-color .3s ease; }
.form__input:focus { border-bottom-color: #DC8541; }
.form__hint { font-size: 12px; color: #8A93A3; line-height: 1.8; }
.form__fieldset { margin: 0; padding: 0; border: none; display: grid; gap: 12px; }
.form__legend { font-size: 13px; font-weight: 500; color: #172E4A; padding: 0; margin-bottom: 4px; }
.form__radio-label { display: flex; align-items: center; gap: 12px; font-size: 15px; color: #3E4A5C; cursor: pointer; }
.form__radio { accent-color: #DC8541; width: 18px; height: 18px; }
.form__other-input { width: 100%; font: inherit; font-size: 16px; color: #172E4A; background: transparent; border: none; border-bottom: 1px solid #D8DCE3; padding: 8px 0; outline: none; margin-left: 30px; max-width: calc(100% - 30px); display: none; }
.form__fieldset.is-other .form__other-input { display: block; }
.form__textarea { width: 100%; font: inherit; font-size: 16px; color: #172E4A; background: #F6F7F9; border: 1px solid #E3E6EB; border-radius: 8px; padding: 14px; outline: none; resize: vertical; transition: border-color .3s ease; }
.form__textarea:focus { border-color: #DC8541; }
.form__checkbox-label { display: flex; align-items: flex-start; gap: 12px; font-size: 14px; color: #3E4A5C; line-height: 1.9; cursor: pointer; }
.form__checkbox { accent-color: #DC8541; width: 18px; height: 18px; margin-top: 3px; }
.form__privacy-link { border-bottom: 1px solid #C7CEDA; }
.form__submit { margin-top: 8px; justify-self: start; display: inline-flex; align-items: center; gap: 14px; background: #DC8541; color: #FFFFFF; font-weight: 600; font-family: Jost, sans-serif; font-size: 14px; letter-spacing: 0.1em; padding: 18px 38px; border: none; border-radius: 999px; cursor: pointer; transition: background .25s ease, transform .15s ease; }
.form__submit:hover { background: #C06E2E; transform: translateY(-1px); }

.thanks { max-width: 640px; border-top: 1px solid #E3E6EB; padding-top: clamp(28px,4vw,40px); display: none; }
.thanks.is-sent { display: block; }
.thanks__eyebrow { margin: 0; font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.2em; color: #DC8541; }
.thanks__title { margin: 16px 0 0; font-size: 17px; font-weight: 500; color: #172E4A; }
.thanks__message { margin: 12px 0 0; font-size: 14px; line-height: 2; color: #56637A; }

/* ============================================
   site-footer（TOPページフッター）
   ============================================ */
.site-footer { background: #172E4A; color: #FFFFFF; padding: clamp(40px,5vw,64px) clamp(20px,5vw,64px) clamp(24px,3vw,32px); margin-top: auto; }
.site-footer__grid { max-width: 1180px; margin: 0 auto; display: flex; flex-wrap: wrap; gap: clamp(24px,4vw,48px); align-items: flex-start; justify-content: space-between; }
.site-footer__name { margin: 0; font-family: Jost, sans-serif; font-size: 18px; letter-spacing: 0.04em; }
.site-footer__role { margin: 8px 0 0; font-size: 12px; color: #7FA0C4; }
.site-footer__social { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 20px; font-size: 12px; letter-spacing: 0.04em; }
.site-footer__social-link { display: inline-flex; align-items: center; gap: 9px; color: #C3D0E0; }
.site-footer__copyright { max-width: 1180px; margin: clamp(28px,4vw,44px) auto 0; font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.12em; color: #4C6689; }

/* ============================================
   icon-slot（アイコン表示）
   ============================================ */
.icon-slot { display: inline-block; flex-shrink: 0; object-fit: contain; }
.icon-slot--social { width: 16px; height: 16px; filter: brightness(0) invert(1); }
.icon-slot--social-muted { opacity: .85; }

